    "fb": "由万能代换：\\(t=\\tan\\frac{x}{2}\\) 时，\\(\\sin x=\\frac{2t}{1+t^2}\\)，\\(\\cos x=\\frac{1-t^2}{1+t^2}\\)，\\(\\mathrm{d}x=\\frac{2}{1+t^2}\\,\\mathrm{d}t\\).于是 \\(R(\\sin x,\\cos x)\\,\\mathrm{d}x\\) 中的 \\(\\sin x,\\cos x\\) 均代成 \\(t\\) 的有理式，\\(\\mathrm{d}x\\) 也是 \\(t\\) 的有理式，整体化为 \\(\\int \\tilde R(t)\\,\\mathrm{d}t\\)，其中 \\(\\tilde R\\) 为有理函数，可按部分分式求解.",
